function foro_url(array $par=[]):string{global $vista;return 'forum.php?'.http_build_query($par+['view'=>$vista]);}
function foro_hidden(string $act,array $par=[]):void{echo '<input type="hidden" name="csrf" value="'.esc($_SESSION['csrf']).'"><input type="hidden" name="action" value="'.$act.'">';foreach($par as $k=>$v)echo '<input type="hidden" name="'.esc($k).'" value="'.esc($v).'">';}
function foro_input(string $nom,string $label,int $max=160,bool $area=false,bool $req=true):void{global $usr;$val=is_string($_POST[$nom]??null)?$_POST[$nom]:($nom==='name'?($usr['nombre']??''):'');echo '<label>'.esc($label);if($area)echo '<textarea name="'.$nom.'" rows="5" maxlength="'.$max.'" '.($req?'required':'').'>'.esc($val).'</textarea>';else echo '<input name="'.$nom.'" maxlength="'.$max.'" value="'.esc($val).'" '.($req?'required':'').'>';echo '</label>';}
function foro_select(string $nom,string $label,array $opts):void{echo '<label>'.esc($label).'<select name="'.$nom.'">';foreach($opts as $k=>$v)echo '<option value="'.$k.'" '.(($_POST[$nom]??'')===$k?'selected':'').'>'.esc($v).'</option>';echo '</select></label>';}
